package net.gsantner.opoc.frontend.textview;

import android.content.SharedPreferences;
import android.content.SharedPreferences.Editor;
import android.text.Editable;
import android.text.Selection;
import android.text.TextWatcher;
import android.text.style.UnderlineSpan;
import android.util.Log;
import android.widget.TextView;
import android.widget.Toast;

import androidx.annotation.Nullable;

import net.gsantner.markor.frontend.textview.TextViewUtils;

import java.io.File;
import java.util.LinkedList;

/**
 * A generic undo/redo implementation for TextViews.
 */
public class TextViewUndoRedo {

    /**
     * Is undo/redo being performed? This member signals if an undo/redo
     * operation is currently being performed. Changes in the text during
     * undo/redo are not recorded because it would mess up the undo history.
     */
    private boolean mIsUndoOrRedo = false;

    /**
     * The edit history.
     */
    private final EditHistory mEditHistory;

    /**
     * The change listener.
     */
    private final EditTextChangeListener mChangeListener;

    /**
     * The edit text.
     */
    private TextView mTextView = null;

    // =================================================================== //

    /**
     * Create a new TextViewUndoRedo
     */
    public TextViewUndoRedo() {
        mEditHistory = new EditHistory();
        mChangeListener = new EditTextChangeListener();
    }

    public void setTextView(final TextView textView) {
        disconnect();
        mTextView = textView;
        mTextView.addTextChangedListener(mChangeListener);
    }

    public String undoRedoPrefKeyForFile(File file) {
        return "file-" + file.getAbsolutePath().replace("/", "-");
    }

    // =================================================================== //

    /**
     * Disconnect this undo/redo from the text view.
     */
    public void disconnect() {
        if (mTextView != null) {
            mTextView.removeTextChangedListener(mChangeListener);
            clearHistory();
        }
    }

    /**
     * Get the currently attached TextView
     */
    public @Nullable TextView getTextView() {
        return mTextView;
    }

    /**
     * Set the maximum history size. If size is negative, then history size is
     * only limited by the device memory.
     */
    public void setMaxHistorySize(int maxHistorySize) {
        mEditHistory.setMaxHistorySize(maxHistorySize);
    }

    /**
     * Clear history.
     */
    public void clearHistory() {
        mEditHistory.clear();
    }

    /**
     * Can undo be performed?
     */
    public boolean getCanUndo() {
        return (mEditHistory.position > 0);
    }

    /**
     * Perform undo.
     */
    public void undo() {
        final EditItem edit = mEditHistory.getPrevious();
        if (edit == null) {
            return;
        }

        final Editable text = mTextView.getEditableText();
        final int start = edit.start;
        final int end = start + (edit.after != null ? edit.after.length() : 0);

        mIsUndoOrRedo = true;
        try {
            text.replace(start, end, edit.before);
        } catch (Exception ex) {
            // In case a undo would crash the app, don't do it instead
            Log.e(getClass().getName(), "undo() Error in text.replace" + ex);
            Toast.makeText(mTextView.getContext(), "undo() Error in text.replace" + ex, Toast.LENGTH_LONG).show();
            return;
        }
        mIsUndoOrRedo = false;

        // This will get rid of underlines inserted when editor tries to come
        // up with a suggestion.
        for (Object o : text.getSpans(0, text.length(), UnderlineSpan.class)) {
            text.removeSpan(o);
        }

        if (edit.selBefore >= 0 && edit.selBefore <= text.length()) {
            Selection.setSelection(text, edit.selBefore);
        }
    }

    /**
     * Can redo be performed?
     */
    public boolean getCanRedo() {
        return (mEditHistory.position < mEditHistory.history.size());
    }

    /**
     * Perform redo.
     */
    public void redo() {
        final EditItem edit = mEditHistory.getNext();
        if (edit == null) {
            return;
        }

        final Editable text = mTextView.getEditableText();
        final int start = edit.start;
        final int end = start + (edit.before != null ? edit.before.length() : 0);

        mIsUndoOrRedo = true;
        text.replace(start, end, edit.after);
        mIsUndoOrRedo = false;

        // This will get rid of underlines inserted when editor tries to come
        // up with a suggestion.
        for (Object o : text.getSpans(0, text.length(), UnderlineSpan.class)) {
            text.removeSpan(o);
        }

        if (edit.selAfter >= 0 && edit.selAfter <= text.length()) {
            Selection.setSelection(text, edit.selAfter);
        }
    }

    /**
     * Store preferences.
     */
    public void storePersistentState(Editor editor, String prefix) {
        // Store hash code of text in the editor so that we can check if the
        // editor contents has changed.
        editor.putString(prefix + ".hash",
                String.valueOf(mTextView.getText().toString().hashCode()));
        editor.putInt(prefix + ".maxSize", mEditHistory._maxHistorySize);
        editor.putInt(prefix + ".position", mEditHistory.position);
        editor.putInt(prefix + ".size", mEditHistory.history.size());

        int i = 0;
        for (EditItem ei : mEditHistory.history) {
            String pre = prefix + "." + i;

            editor.putInt(pre + ".start", ei.start);
            editor.putString(pre + ".before", ei.before.toString());
            editor.putString(pre + ".after", ei.after.toString());

            i++;
        }
    }

    /**
     * Restore preferences.
     *
     * @param prefix The preference key prefix used when state was stored.
     * @return did restore succeed? If this is false, the undo history will be
     * empty.
     */
    public boolean restorePersistentState(SharedPreferences sp, String prefix)
            throws IllegalStateException {

        boolean ok = doRestorePersistentState(sp, prefix);
        if (!ok) {
            mEditHistory.clear();
        }

        return ok;
    }

    private boolean doRestorePersistentState(SharedPreferences sp, String prefix) {

        String hash = sp.getString(prefix + ".hash", null);
        if (hash == null) {
            // No state to be restored.
            return true;
        }

        if (Integer.parseInt(hash) != mTextView.getText().toString().hashCode()) {
            return false;
        }

        mEditHistory.clear();
        mEditHistory._maxHistorySize = sp.getInt(prefix + ".maxSize", -1);

        int count = sp.getInt(prefix + ".size", -1);
        if (count == -1) {
            return false;
        }

        for (int i = 0; i < count; i++) {
            String pre = prefix + "." + i;

            int start = sp.getInt(pre + ".start", -1);
            String before = sp.getString(pre + ".before", null);
            String after = sp.getString(pre + ".after", null);

            if (start == -1 || before == null || after == null) {
                return false;
            }
            mEditHistory.add(new EditItem(start, before, after, -1, -1));
        }

        mEditHistory.position = sp.getInt(prefix + ".position", -1);
        return mEditHistory.position != -1;
    }

    // =================================================================== //

    /**
     * Keeps track of all the edit history of a text.
     */
    private static final class EditHistory {

        /**
         * The position from which an EditItem will be retrieved when getNext()
         * is called. If getPrevious() has not been called, this has the same
         * value as mmHistory.size().
         */
        private int position = 0;

        /**
         * Maximum undo history size.
         */
        private int _maxHistorySize = -1;

        /**
         * The list of edits in chronological order.
         */
        private final LinkedList<EditItem> history = new LinkedList<>();

        /**
         * Clear history.
         */
        private void clear() {
            position = 0;
            history.clear();
        }

        /**
         * Adds a new edit operation to the history at the current position. If
         * executed after a call to getPrevious() removes all the future history
         * (elements with positions >= current history position).
         */
        private void add(final EditItem item) {
            if (item == null || item.zeroChange()) {
                return;
            }

            while (history.size() > position) {
                history.removeLast();
            }
            history.add(item);
            position++;

            if (_maxHistorySize >= 0) {
                trimHistory();
            }
        }

        /**
         * Set the maximum history size. If size is negative, then history size
         * is only limited by the device memory.
         */
        private void setMaxHistorySize(int maxHistorySize) {
            _maxHistorySize = maxHistorySize;
            if (_maxHistorySize >= 0) {
                trimHistory();
            }
        }

        /**
         * Trim history when it exceeds max history size.
         */
        private void trimHistory() {
            while (history.size() > _maxHistorySize) {
                history.removeFirst();
                position--;
            }

            if (position < 0) {
                position = 0;
            }
        }

        /**
         * Traverses the history backward by one position, returns and item at
         * that position.
         */
        private EditItem getPrevious() {
            if (position == 0) {
                return null;
            }
            position--;
            return history.get(position);
        }

        /**
         * Traverses the history forward by one position, returns and item at
         * that position.
         */
        private EditItem getNext() {
            if (position >= history.size()) {
                return null;
            }

            EditItem item = history.get(position);
            position++;
            return item;
        }
    }

    /**
     * Represents the changes performed by a single edit operation.
     */
    private static final class EditItem {
        private final int start;
        private final String before;
        private final String after;

        private final int selBefore, selAfter;

        /**
         * Constructs EditItem of a modification that was applied at position
         * start and replaced CharSequence before with CharSequence after.
         */
        public EditItem(
                final int start,
                final String before,
                final String after,
                final int selBefore,
                final int selAfter
        ) {
            // Made change minimal
            final int[] diff = TextViewUtils.findDiff(before, after, 0, 0);
            this.start = start + diff[0];
            this.before = before.substring(diff[0], diff[1]);
            this.after = after.substring(diff[0], diff[2]);

            this.selBefore = selBefore;
            this.selAfter = selAfter;
        }

        public boolean zeroChange() {
            return before.equals(after);
        }

        public boolean equals(final EditItem other) {
            return other != null && start == other.start && before.equals(other.before) && after.equals(other.after);
        }
    }

    /**
     * Class that listens to changes in the text.
     */
    private final class EditTextChangeListener implements TextWatcher {

        /**
         * The text that will be removed by the change event.
         */
        private String beforeChange, afterChange;
        private boolean isInChain = false;
        private long lastTime = 0;
        private int selBefore = -1;
        private int changeStart = -1;


        public void beforeTextChanged(CharSequence s, int start, int count, int after) {
            if (mIsUndoOrRedo) {
                return;
            }

            beforeChange = TextViewUtils.toString(s, start, start + count);
            selBefore = Selection.getSelectionStart(s);
        }

        public void onTextChanged(final CharSequence s, int start, int before, int count) {
            if (mIsUndoOrRedo) {
                return;
            }
            afterChange = TextViewUtils.toString(s, start, start + count);
            changeStart = start;
        }

        public void afterTextChanged(final Editable s) {
            if (mIsUndoOrRedo) {
                return;
            }

            final int selAfter = Selection.getSelectionStart(s);
            final EditItem cur = new EditItem(changeStart, beforeChange, afterChange, selBefore, selAfter);

            // Sometimes autocorrect inserts a zero change. Ignore this.
            if (cur.zeroChange()) {
                return;
            }

            // Get previous and new items
            final EditItem prev;
            if (mEditHistory.position == mEditHistory.history.size()) {
                prev = mEditHistory.getPrevious();
            } else {
                prev = null;
            }

            // Sometimes the text watcher is called for the same change 2x. Ignore this.
            if (cur.equals(prev)) {
                mEditHistory.add(prev);
                return;
            }

            // 5 second time within which we will combine
            final long delta = System.currentTimeMillis() - lastTime;
            lastTime += delta;

            // Attempt to combine if conditions are met
            if (delta < 5000 && prev != null && !prev.zeroChange()) {

                final int pbl = prev.before.length();
                final int pal = prev.after.length();
                final int cbl = cur.before.length();
                final int cal = cur.after.length();

                final int newStart = Math.min(prev.start, cur.start);

                final boolean insChain = pbl == 0 && (isInChain || pal == 1);
                final boolean singleIns = cbl == 0 && cal == 1;
                final boolean insFollows = cur.start == (prev.start + pal);

                // Combine if adding multiple of same class or trailing space
                if (singleIns && insChain && insFollows) {
                    final int chainType = typeOf(prev.after.charAt(pal - 1));
                    final int insType = typeOf(cur.after.charAt(0));
                    if (chainType == insType || (chainType == CHAR && insType == SPACE)) {
                        // Not in chain if char chain followed by space
                        isInChain = chainType == insType;
                        mEditHistory.add(new EditItem(newStart, "", prev.after + cur.after, prev.selBefore, cur.selAfter));
                        return;
                    }
                }

                final boolean delChain = pal == 0 && (isInChain || pbl == 1);
                final boolean singleDel = cal == 0 && cbl == 1;
                final boolean delFollows = cur.start == (prev.start - cbl);

                // Combine if removing multiple of same class or trailing space
                if (singleDel && delChain && delFollows) {
                    final int chainType = typeOf(prev.before.charAt(0));
                    final int delType = typeOf(cur.before.charAt(0));
                    if (chainType == delType || (chainType == CHAR && delType == SPACE)) {
                        isInChain = chainType == delType;
                        mEditHistory.add(new EditItem(newStart, cur.before + prev.before, "", prev.selBefore, cur.selAfter));
                        return;
                    }
                }
            }

            // Else add both prev and cur back - null and empty handled automatically
            isInChain = false;
            mEditHistory.add(prev);
            mEditHistory.add(cur);
        }

        final int CHAR = 0, SPACE = 1, NL = 2;

        private int typeOf(final char c) {
            switch (c) {
                case '\n':
                    return NL;
                case ' ':
                    return SPACE;
                default:
                    return CHAR;
            }
        }
    }
}

import { Operation } from 'slate';

import type { YooptaOperation } from './applyTransforms';
import { Blocks } from '../blocks';
import type { SlateElement, YooEditor, YooptaPath } from '../types';

export type HistoryStack = {
  operations: YooptaOperation[];
  path: YooptaPath;
};

export type HistoryStackName = 'undos' | 'redos';

export function inverseEditorOperation(
  editor: YooEditor,
  op: YooptaOperation,
): YooptaOperation | YooptaOperation[] {
  switch (op.type) {
    case 'insert_block':
      return {
        type: 'delete_block',
        path: op.path,
        block: op.block,
      };

    case 'delete_block':
      return {
        type: 'insert_block',
        path: op.path,
        block: op.block,
      };

    case 'set_block_meta': {
      return {
        type: 'set_block_meta',
        id: op.id,
        properties: op.prevProperties,
        prevProperties: op.properties,
      };
    }

    case 'split_block': {
      return [
        {
          type: 'delete_block',
          block: op.properties.nextBlock,
          path: op.path,
        },
        {
          type: 'set_block_value',
          id: op.prevProperties.originalBlock.id,
          value: op.prevProperties.originalValue as SlateElement[],
          forceSlate: true,
        },
      ];
    }

    case 'toggle_block': {
      return {
        type: 'toggle_block',
        properties: {
          toggledBlock: op.prevProperties.sourceBlock,
          toggledSlateValue: op.prevProperties.sourceSlateValue,
        },
        prevProperties: {
          sourceBlock: op.properties.toggledBlock,
          sourceSlateValue: op.properties.toggledSlateValue,
        },
      };
    }

    case 'merge_block': {
      return [
        {
          type: 'split_block',
          properties: {
            nextBlock: op.prevProperties.sourceBlock,
            nextSlateValue: op.prevProperties.sourceSlateValue,
            splitSlateValue: op.prevProperties.targetSlateValue,
          },
          prevProperties: {
            originalBlock: op.properties.mergedBlock,
            originalValue: op.properties.mergedSlateValue,
          },
          path: op.path,
        },
      ];
    }

    case 'move_block': {
      return {
        type: 'move_block',
        properties: op.prevProperties,
        prevProperties: op.properties,
      };
    }

    case 'set_slate': {
      const inverseOps = op.properties.slateOps.map(Operation.inverse).reverse();
      return {
        type: 'set_slate',
        properties: {
          slateOps: inverseOps,
          selectionBefore: op.properties.selectionBefore,
        },
        slate: op.slate,
        blockId: op.blockId,
      };
    }

    case 'set_editor_value': {
      return {
        type: 'set_editor_value',
        properties: op.prevProperties,
        prevProperties: op.properties,
      };
    }

    default:
      return op;
  }
}

export type UndoRedoOptions = {
  scroll?: boolean;
};

export const SAVING = new WeakMap<YooEditor, boolean | undefined>();
export const MERGING = new WeakMap<YooEditor, boolean | undefined>();

export const YooptaHistory = {
  isMergingHistory(editor: YooEditor): boolean | undefined {
    return MERGING.get(editor);
  },

  isSavingHistory(editor: YooEditor): boolean | undefined {
    return SAVING.get(editor);
  },

  withMergingHistory(editor: YooEditor, fn: () => void): void {
    const prev = YooptaHistory.isMergingHistory(editor);
    MERGING.set(editor, true);
    fn();
    MERGING.set(editor, prev);
  },

  withSavingHistory(editor: YooEditor, fn: () => void): void {
    const prev = YooptaHistory.isSavingHistory(editor);
    SAVING.set(editor, true);
    fn();
    SAVING.set(editor, prev);
  },

  withoutMergingHistory(editor: YooEditor, fn: () => void): void {
    const prev = YooptaHistory.isMergingHistory(editor);
    MERGING.set(editor, false);
    fn();
    MERGING.set(editor, prev);
  },

  withoutSavingHistory(editor: YooEditor, fn: () => void): void {
    const prev = YooptaHistory.isSavingHistory(editor);
    SAVING.set(editor, false);
    fn();
    SAVING.set(editor, prev);
  },

  redo: (editor: YooEditor, options?: UndoRedoOptions) => {
    const { redos } = editor.historyStack;

    if (redos.length > 0) {
      const batch = redos[redos.length - 1];

      YooptaHistory.withoutSavingHistory(editor, () => {
        editor.applyTransforms(batch.operations, { source: 'history' });
        editor.setPath(batch.path);

        const { scroll = true } = options || {};
        if (scroll && typeof batch.path.current === 'number') {
          const block = Blocks.getBlock(editor, { at: batch.path.current });

          // [TODO] - not good place to scroll. View tasks should be separated from model tasks
          const blockElement = document.querySelector(`[data-yoopta-block-id="${block?.id}"]`);
          if (blockElement && !isInViewport(blockElement)) {
            blockElement.scrollIntoView({ block: 'center', behavior: 'auto' });
          }
        }
      });

      editor.historyStack.redos.pop();
      editor.historyStack.undos.push(batch);
    }
  },
  undo: (editor: YooEditor, options?: UndoRedoOptions) => {
    const { undos } = editor.historyStack;

    if (undos.length > 0) {
      const batch = editor.historyStack.undos[editor.historyStack.undos.length - 1];

      YooptaHistory.withoutSavingHistory(editor, () => {
        // [TODO] - ask Christopher Nolan to help with this
        const inverseOps = batch.operations
          .flatMap((op) => inverseEditorOperation(editor, op))
          .reverse();
        editor.applyTransforms(inverseOps, { source: 'history' });
        editor.setPath(batch.path);

        const { scroll = true } = options || {};
        if (scroll && typeof batch.path.current === 'number') {
          const block = Blocks.getBlock(editor, { at: batch.path.current });

          // [TODO] - not good place to scroll. View tasks should be separated from model tasks
          const blockElement = document.querySelector(`[data-yoopta-block-id="${block?.id}"]`);
          if (blockElement && !isInViewport(blockElement)) {
            blockElement.scrollIntoView({ block: 'center', behavior: 'auto' });
          }
        }
      });

      editor.historyStack.redos.push(batch);
      editor.historyStack.undos.pop();
    }
  },
};

function isInViewport(element) {
  const rect = element.getBoundingClientRect();
  const html = document.documentElement;
  return (
    rect.top >= 0 &&
    rect.left >= 0 &&
    rect.bottom <= (window.innerHeight || html.clientHeight) &&
    rect.right <= (window.innerWidth || html.clientWidth)
  );
}

/**
 * Phase 8: Boolean History Tracking Tests
 *
 * Tests the tracking of faces through boolean operations using Modified() and IsDeleted() APIs.
 * This enables persistent references to survive boolean operations.
 *
 * @see docs/CAD-PIPELINE-REWORK.md Phase 8
 * @see docs/BOOLEAN-HISTORY-OPTIONS.md
 */

import { describe, it, expect, beforeAll } from "vitest";
import {
  initOCCT,
  setOC,
  booleanOpWithHistory,
  extrude,
  sketchProfileToFace,
  getPlaneNormal,
} from "../../src/kernel/index.js";
import { XY_PLANE } from "../../src/model/planes.js";
import { createRectangleProfile } from "../../src/model/sketchProfile.js";

describe("Boolean History Tracking (Phase 8)", () => {
  beforeAll(async () => {
    const oc = await initOCCT();
    setOC(oc);
  });

  describe("booleanOpWithHistory", () => {
    it("returns face mappings for union of overlapping boxes", () => {
      // Create two overlapping boxes
      const profile1 = createRectangleProfile(XY_PLANE, 20, 20, 0, 0);
      const face1 = sketchProfileToFace(profile1);
      const box1 = extrude(face1, getPlaneNormal(profile1.plane), 20);

      const profile2 = createRectangleProfile(XY_PLANE, 20, 20, 10, 0);
      const face2 = sketchProfileToFace(profile2);
      const box2 = extrude(face2, getPlaneNormal(profile2.plane), 20);

      // Perform union with history
      const result = booleanOpWithHistory(box1, box2, "union");

      expect(result.success).toBe(true);
      expect(result.shape).toBeDefined();
      expect(result.baseFaceMap).toBeDefined();
      expect(result.toolFaceMap).toBeDefined();

      // Both boxes have 6 faces
      expect(result.baseFaceMap!.length).toBe(6);
      expect(result.toolFaceMap!.length).toBe(6);

      // Count different fates
      const baseDeleted = result.baseFaceMap!.filter((m) => m.isDeleted).length;
      const baseModified = result.baseFaceMap!.filter(
        (m) => !m.isDeleted && m.outputHashes.length > 0
      ).length;
      const toolDeleted = result.toolFaceMap!.filter((m) => m.isDeleted).length;
      const toolModified = result.toolFaceMap!.filter(
        (m) => !m.isDeleted && m.outputHashes.length > 0
      ).length;

      console.log(`Base: ${baseDeleted} deleted, ${baseModified} modified/unchanged`);
      console.log(`Tool: ${toolDeleted} deleted, ${toolModified} modified/unchanged`);

      // Some faces should be deleted (internal faces where boxes overlap)
      expect(baseDeleted + toolDeleted).toBeGreaterThan(0);

      // Some faces should be modified or unchanged
      expect(baseModified + toolModified).toBeGreaterThan(0);

      // Cleanup
      result.shape!.dispose();
      box1.dispose();
      box2.dispose();
      face1.dispose();
      face2.dispose();
    });

    it("returns face mappings for subtraction (cut)", () => {
      // Create base box and cutting box
      const profile1 = createRectangleProfile(XY_PLANE, 30, 30, 0, 0);
      const face1 = sketchProfileToFace(profile1);
      const baseBox = extrude(face1, getPlaneNormal(profile1.plane), 20);

      const profile2 = createRectangleProfile(XY_PLANE, 10, 10, 0, 0);
      const face2 = sketchProfileToFace(profile2);
      const cutter = extrude(face2, getPlaneNormal(profile2.plane), 30);

      // Perform subtraction with history
      const result = booleanOpWithHistory(baseBox, cutter, "subtract");

      expect(result.success).toBe(true);
      expect(result.shape).toBeDefined();
      expect(result.baseFaceMap).toBeDefined();
      expect(result.toolFaceMap).toBeDefined();

      // Check that we get history for both shapes
      expect(result.baseFaceMap!.length).toBe(6);
      expect(result.toolFaceMap!.length).toBe(6);

      // In a cut, the tool faces that create the pocket should be tracked
      // Some base faces should be modified (the top face gets a hole)
      const baseModified = result.baseFaceMap!.filter(
        (m) => !m.isDeleted && m.outputHashes.length > 1
      );
      console.log(`Base faces split into multiple: ${baseModified.length}`);

      // Cleanup
      result.shape!.dispose();
      baseBox.dispose();
      cutter.dispose();
      face1.dispose();
      face2.dispose();
    });

    it("tracks unchanged faces correctly", () => {
      // Create two non-overlapping boxes that only touch at an edge
      const profile1 = createRectangleProfile(XY_PLANE, 10, 10, -10, 0);
      const face1 = sketchProfileToFace(profile1);
      const box1 = extrude(face1, getPlaneNormal(profile1.plane), 10);

      const profile2 = createRectangleProfile(XY_PLANE, 10, 10, 10, 0);
      const face2 = sketchProfileToFace(profile2);
      const box2 = extrude(face2, getPlaneNormal(profile2.plane), 10);

      // Perform union with history
      const result = booleanOpWithHistory(box1, box2, "union");

      expect(result.success).toBe(true);

      // Most faces should be unchanged (outputHash === inputHash)
      const baseUnchanged = result.baseFaceMap!.filter(
        (m) => !m.isDeleted && m.outputHashes.length === 1 && m.outputHashes[0] === m.inputHash
      );
      const toolUnchanged = result.toolFaceMap!.filter(
        (m) => !m.isDeleted && m.outputHashes.length === 1 && m.outputHashes[0] === m.inputHash
      );

      console.log(`Base unchanged: ${baseUnchanged.length}/6`);
      console.log(`Tool unchanged: ${toolUnchanged.length}/6`);

      // Most faces should survive unchanged for non-overlapping boxes
      expect(baseUnchanged.length + toolUnchanged.length).toBeGreaterThanOrEqual(8);

      // Cleanup
      result.shape!.dispose();
      box1.dispose();
      box2.dispose();
      face1.dispose();
      face2.dispose();
    });

    it("provides output hashes that can be used for tracking", () => {
      // Create overlapping boxes
      const profile1 = createRectangleProfile(XY_PLANE, 20, 20, 0, 0);
      const face1 = sketchProfileToFace(profile1);
      const box1 = extrude(face1, getPlaneNormal(profile1.plane), 20);

      const profile2 = createRectangleProfile(XY_PLANE, 20, 20, 5, 5);
      const face2 = sketchProfileToFace(profile2);
      const box2 = extrude(face2, getPlaneNormal(profile2.plane), 20);

      const result = booleanOpWithHistory(box1, box2, "union");

      expect(result.success).toBe(true);

      // Collect all output hashes from both face maps
      const allOutputHashes = new Set<number>();
      for (const mapping of result.baseFaceMap!) {
        for (const hash of mapping.outputHashes) {
          allOutputHashes.add(hash);
        }
      }
      for (const mapping of result.toolFaceMap!) {
        for (const hash of mapping.outputHashes) {
          allOutputHashes.add(hash);
        }
      }

      console.log(`Total unique output face hashes: ${allOutputHashes.size}`);

      // Should have some output faces
      expect(allOutputHashes.size).toBeGreaterThan(0);

      // Cleanup
      result.shape!.dispose();
      box1.dispose();
      box2.dispose();
      face1.dispose();
      face2.dispose();
    });
  });
